/* Campus Connect — interactive frontend. All important mutations call the FastAPI backend. */
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = (name='User') => name.split(/\s+/).filter(Boolean).slice(0,2).map(p=>p[0]).join('').toUpperCase();
const dateFmt = (v, options={month:'short',day:'numeric',year:'numeric'}) => { if(!v) return 'Date TBC'; const d = new Date(String(v).length===10?`${v}T12:00:00`:v); return isNaN(d) ? esc(v) : d.toLocaleDateString('en-IN', options); };
const timeAgo = v => { if(!v) return ''; const d=new Date(v), sec=Math.max(0,(Date.now()-d.getTime())/1000); if(sec<60)return 'Just now'; if(sec<3600)return `${Math.floor(sec/60)}m ago`; if(sec<86400)return `${Math.floor(sec/3600)}h ago`; if(sec<604800)return `${Math.floor(sec/86400)}d ago`; return dateFmt(v,{month:'short',day:'numeric'}); };
const parseLines = (text, kind) => (text||'').split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{const [name,url='',details='']=line.split('|').map(s=>s.trim()); return kind==='project'?{name,url,description:details,evidence_status:'self_reported'}:{name,outcome:url, evidence_url:details,verification_status:'self_reported'};});
const linesFor = (list, kind) => (list||[]).map(x=>kind==='project'?[x.name||'',x.url||'',x.description||''].filter((v,i)=>v||i===0).join(' | '):[x.name||'',x.outcome||'',x.evidence_url||''].filter((v,i)=>v||i===0).join(' | ')).join('\n');

const state = {
  user:null, route:'overview', dashboard:null, events:[], teams:[], openTeams:[], inbox:null,
  currentTeam:null, matchResult:null, matchRole:'primary', githubResults:null, githubQuery:'',
  modal:null, loading:{}, eventFilters:{q:'',location:'',category:'all',status:'upcoming'}, findEventId:'', toastTimer:null,
  adminData:null, focusRunId:null, profileCache:null, demoEnabled:false
};

async function api(path, options={}) {
  const opts={method:options.method||'GET',headers:{...(options.headers||{})}};
  if(options.body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(options.body);}
  const res=await fetch(path,opts);
  let data={}; try{data=await res.json()}catch(_){data={detail:`Server returned ${res.status}`}}
  if(!res.ok){ if(res.status===401 && state.user){state.user=null;state.dashboard=null;render();} throw new Error(data.detail||`Request failed (${res.status})`); }
  return data;
}
function toast(message, type='success', note=''){
  const region=$('#toast-region'); if(!region)return; const el=document.createElement('div'); el.className=`toast ${type}`; el.innerHTML=`${esc(message)}${note?`<small>${esc(note)}</small>`:''}`; region.appendChild(el); setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(7px)';setTimeout(()=>el.remove(),220)},3600);
}
function setLoading(key, value){state.loading[key]=value;}
function navTitle(route){return ({overview:'Overview','discover':'Discover events','find-team':'Find your team','my-teams':'My teams','team-detail':'Team workspace','github':'GitHub research','inbox':'Inbox','profile':'My profile','admin':'Admin & trust'})[route]||'Campus Connect';}
function navigate(route, params={}){
  state.route=route;
  if(params.teamId!==undefined){state.selectedTeamId=params.teamId;state.currentTeam=null;state.matchResult=null;state.focusRunId=null;}
  if(params.eventId!==undefined){state.findEventId=String(params.eventId||'');state.selectedEventId=params.eventId||null;}
  if(params.runId!==undefined){state.focusRunId=params.runId;}
  state.modal=null;
  render();
  loadRouteData(route).catch(e=>toast(e.message,'error'));
  if(window.innerWidth<980){$('#sidebar')?.classList.remove('open');$('#mobile-overlay')?.classList.remove('show');}
}
async function loadRouteData(route){
  if(!state.user)return;
  if(route==='overview'){await refreshDashboard();}
  else if(route==='discover'){await loadEvents();}
  else if(route==='find-team'){await Promise.all([loadEvents(),loadOpenTeams()]);}
  else if(route==='my-teams'){await loadTeams();}
  else if(route==='team-detail'){if(state.selectedTeamId) await loadTeam(state.selectedTeamId);}
  else if(route==='inbox'){await loadInbox();}
  else if(route==='profile'){await loadProfile();}
  else if(route==='admin'){await loadAdmin();}
  render();
}
async function refreshDashboard(){
  const [d,e,t] = await Promise.all([api('/api/dashboard'),api('/api/events?status=all'),api('/api/teams')]);
  state.dashboard=d; state.user=d.profile; state.events=e.events; state.teams=t.teams;
}
async function loadEvents(){
  const f=state.eventFilters; const qs=new URLSearchParams(); if(f.q)qs.set('q',f.q); if(f.location)qs.set('location',f.location); if(f.category && f.category!=='all')qs.set('category',f.category); if(f.status && f.status!=='all')qs.set('status',f.status);
  const d=await api(`/api/events?${qs.toString()}`);state.events=d.events;state.eventDataNotice=d.data_mode;
}
async function loadTeams(){const d=await api('/api/teams');state.teams=d.teams;}
async function loadOpenTeams(){const qs=state.findEventId?`?event_id=${encodeURIComponent(state.findEventId)}`:'';const d=await api(`/api/teams/open${qs}`);state.openTeams=d.teams;}
async function loadTeam(id){const d=await api(`/api/teams/${id}`);state.currentTeam=d;if(state.focusRunId){try{const run=await api(`/api/agent/runs/${state.focusRunId}`);state.matchResult={...run.run.result,run_id:run.run.id,logs:run.events};state.matchRole=run.run.result?.target_role||((run.run.goal||'').toLowerCase().includes('backup')?'backup':'primary');}catch(_){}}else if(d.latest_runs?.length){const first=d.latest_runs[0];if(first.result?.candidates?.length){state.matchResult={...first.result,run_id:first.id,logs:[]};state.matchRole=first.result?.target_role||((first.goal||'').toLowerCase().includes('backup')?'backup':'primary');}}
}
async function loadInbox(){state.inbox=await api('/api/inbox');}
async function loadProfile(){const d=await api('/api/me');state.user=d.user;state.profileCache=d.user;}
async function loadAdmin(){const [overview,cases,proposals,people]=await Promise.all([api('/api/admin/overview'),api('/api/admin/deserter-cases'),api('/api/admin/event-proposals'),api('/api/admin/people')]);state.adminData={overview,cases:cases.cases,proposals:proposals.proposals,people:people.people||[],peopleDemoMode:people.demo_mode};}
async function loadGithubEvidence(){const d=await api('/api/github/my-evidence');state.githubEvidence=d;}

function render(){
  const root=$('#app');
  if(!state.user){root.innerHTML=renderAuth();bindLoginDemo();return;}
  root.innerHTML=`<div class="app-shell"><div id="mobile-overlay" class="mobile-overlay"></div>${renderSidebar()}<main class="main-area"><header class="topbar"><div class="topbar-left"><button class="hamburger" data-action="toggle-menu" aria-label="Open navigation">☰</button><div><div class="breadcrumb">Campus Connect <span style="margin:0 5px;color:#c0c7d4">/</span> Workspace</div><h1>${esc(navTitle(state.route))}</h1></div></div><div class="topbar-right"><div class="top-search"><span>⌕</span><input id="global-search" placeholder="Search events, skills…" aria-label="Search events or skills" value="${state.route==='discover'?esc(state.eventFilters.q):''}"></div><button class="top-icon-btn" data-nav="inbox" title="Inbox">✉${(state.dashboard?.unread_count||0)>0?'<i class="notif-dot"></i>':''}</button><button class="top-icon-btn" data-nav="profile" title="My profile">${esc(initials(state.user.name))}</button></div></header><div class="page-content">${renderPage()}</div></main></div>${renderModal()}`;
}

function renderAuth(){return `<div class="auth-layout"><section class="auth-visual"><div class="auth-brand"><div class="brand-lockup"><div class="brand-mark">CC</div><div>campus<span>connect</span><small>Opportunity · People · Teams</small></div></div></div><div class="auth-copy"><div class="auth-eyebrow"><span class="live-dot"></span> AGENTIC AI FOR STUDENT TEAMS</div><h1>Find your people.<br>Build something <em>real.</em></h1><p>Discover relevant hackathons, meet teammates who fill the gaps, keep one backup in reserve, and let coordinated agents help your team recover when plans change.</p><div class="auth-feature-list"><div class="auth-feature"><span class="feature-icon">✦</span> Event-aware, explainable teammate matching</div><div class="auth-feature"><span class="feature-icon">↻</span> One-backup protection and team recovery</div><div class="auth-feature"><span class="feature-icon">⌘</span> GitHub research and a built-in team inbox</div></div></div><div class="auth-footer">Built for the Phantom Agents · Agentic AI track</div></section><section class="auth-panel"><div class="auth-card"><div class="eyebrow">YOUR NEXT TEAM STARTS HERE</div><h2 id="auth-title">Welcome back</h2><p class="auth-sub" id="auth-sub">Sign in to continue discovering events and building your team.</p><div id="auth-error"></div><form id="login-form"><div class="field"><label for="login-email">Email address</label><input id="login-email" name="email" type="email" autocomplete="username" required placeholder="you@college.edu"></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" autocomplete="current-password" required placeholder="Enter your password"></div><button class="btn btn-primary btn-block" type="submit">Sign in to Campus Connect <span>→</span></button></form><form id="register-form" class="hidden"><div class="field"><label for="reg-name">Full name</label><input id="reg-name" name="name" required minlength="2" maxlength="80" placeholder="Your name"></div><div class="field"><label for="reg-email">Email address</label><input id="reg-email" name="email" type="email" required placeholder="you@college.edu"></div><div class="field"><label for="reg-password">Password</label><input id="reg-password" name="password" type="password" required minlength="8" placeholder="At least 8 characters"></div><div class="field"><label for="reg-college">College / institution</label><input id="reg-college" name="college" placeholder="Your college"></div><div class="field"><label for="reg-city">City</label><input id="reg-city" name="city" value="Chennai" placeholder="Chennai"></div><button class="btn btn-primary btn-block" type="submit">Create my account <span>→</span></button></form><div class="auth-toggle"><span id="auth-toggle-copy">New to Campus Connect?</span> <button class="text-btn" data-action="toggle-auth-mode" id="auth-toggle-btn">Create an account</button></div>${state.demoEnabled?`<div class="demo-box"><div class="demo-box-top"><b>Explore with a demo account</b><span>Sample data only</span></div><div class="demo-account-grid" id="demo-accounts"><button type="button" class="demo-account" data-demo-email="captain@campusconnect.demo">Olivia · Captain<small>Run Team Architect & recovery</small></button><button type="button" class="demo-account" data-demo-email="arjun@campusconnect.demo">Arjun · Backend<small>Accept or decline invitations</small></button><button type="button" class="demo-account" data-demo-email="karthik@campusconnect.demo">Karthik · AI/ML<small>Candidate experience</small></button><button type="button" class="demo-account" data-demo-email="admin@campusconnect.demo">Admin workspace<small>Review event and trust reports</small></button></div><div class="input-hint" style="margin-top:9px">Demo password: <b>Campus123!</b>. All demo people and events are synthetic.</div></div>`:''}<div class="auth-notice">The app works locally without an LLM API key. Agent tools, scoring, workflows, and state changes run in the backend. Configure <code>SARVAM_API_KEY</code> and <code>AI_PROVIDER=sarvam</code> for Sarvam AI tool-use review; OpenAI-compatible APIs are also supported.</div></div></section></div>`;}
function bindLoginDemo(){ /* Delegated clicks handle demo account choices. */ }
function renderSidebar(){const nav=[{section:'WORKSPACE',items:[['overview','⌂','Overview'],['discover','✦','Discover events'],['find-team','♧','Find a team'],['my-teams','◈','My teams']]},{section:'TOOLS',items:[['inbox','✉','Inbox']]},{section:'ACCOUNT',items:[['profile','◉','My profile']] }];let out=`<aside class="sidebar" id="sidebar"><div class="sidebar-brand"><div class="brand-mark">CC</div><div class="sidebar-brand-name">campus connect<small>Student opportunity network</small></div></div>`;for(const group of nav){out+=`<div class="nav-label">${group.section}</div><div class="nav-list">`;for(const [route,icon,label] of group.items){const count=route==='inbox'?(state.dashboard?.unread_count||0):0;out+=`<button class="nav-item ${state.route===route||state.route==='team-detail'&&route==='my-teams'?'active':''}" data-nav="${route}"><span class="nav-icon">${icon}</span>${label}${count?`<span class="nav-count">${count}</span>`:''}</button>`;}out+='</div>';}
if(state.user.is_admin){out+=`<div class="nav-label">MANAGE</div><div class="nav-list"><button class="nav-item ${state.route==='admin'?'active':''}" data-nav="admin"><span class="nav-icon">⚑</span>Admin & trust</button></div>`;}
out+=`<div class="sidebar-spacer"></div><div class="agent-mini"><div class="agent-mini-head"><span class="live-dot"></span> Agent workflow</div><p>Scout, profile intelligence, Team Architect and recovery workflows share persisted state and real tools.</p><div class="agent-mini-foot">↗ TOOL EXECUTION ACTIVE</div></div><div class="sidebar-user"><div class="avatar">${esc(initials(state.user.name))}</div><div class="sidebar-user-info"><b>${esc(state.user.name)}</b><small>${state.user.is_demo?'Demo account':esc(state.user.college||'Student account')}</small></div><button class="logout-btn" data-action="logout" title="Sign out">↪</button></div></aside>`;return out;}
function renderPage(){switch(state.route){case'discover':return renderDiscover();case'find-team':return renderFindTeam();case'my-teams':return renderMyTeams();case'team-detail':return renderTeamDetail();case'github':return renderGithub();case'inbox':return renderInbox();case'profile':return renderProfile();case'admin':return renderAdmin();default:return renderOverview();}}

function scoreRing(score, sizeClass=''){return `<div class="score-ring ${sizeClass}" style="--score:${Number(score||0)}%"><div class="score-ring-inner"><strong>${Number(score||0)}</strong><small> / 100</small></div></div>`;}
function renderScoreBreakdown(profile){if(!profile?.components)return '';return `<div class="score-breakdown">${profile.components.map(c=>`<div class="score-line"><label>${esc(c.label)} <span style="color:#a2adbd">${c.weight}%</span></label><div class="progress"><span style="width:${Number(c.score)}%"></span></div><b>${Number(c.score)}</b></div>`).join('')}</div>`;}
function renderOverview(){const d=state.dashboard;if(!d)return loadingBlock('Loading your workspace…');const p=d.profile, profile=p.overall_profile_score||{score:0};const events=(d.events||[]).slice(0,3);return `<section class="hero"><div class="hero-content"><div class="eyebrow"><span class="live-dot"></span> YOUR NEXT BUILD STARTS HERE</div><h2>Great ideas need<br>the <span style="color:#8cf0de">right team.</span></h2><p>Campus Connect finds opportunities that fit you, assembles balanced teams, and helps them stay ready when plans change.</p><div class="hero-actions"><button class="btn btn-primary" data-nav="discover">Explore hackathons <span>↗</span></button><button class="btn btn-outline" data-nav="find-team">Find my team <span>→</span></button><button class="btn btn-ghost" data-nav="github">Research repositories ↗</button></div></div><div class="hero-visual"><div class="orbit"><div class="orbit-core">CC</div><div class="orbit-node n1">✦</div><div class="orbit-node n2">⌘</div><div class="orbit-node n3">♧</div><div class="orbit-node n4">↻</div></div></div></section><div class="grid grid-4"><div class="stat-card"><div class="stat-icon teal">✦</div><div><div class="stat-value">${d.stats.events}</div><div class="stat-label">Opportunities listed</div><div class="stat-caption">Event database</div></div></div><div class="stat-card"><div class="stat-icon purple">◈</div><div><div class="stat-value">${d.stats.teams}</div><div class="stat-label">Your teams</div><div class="stat-caption">Including past collaborations</div></div></div><div class="stat-card"><div class="stat-icon orange">✉</div><div><div class="stat-value">${d.unread_count}</div><div class="stat-label">Unread messages</div><div class="stat-caption">Invitations & updates</div></div></div><div class="stat-card"><div class="stat-icon blue">↗</div><div><div class="stat-value">${d.stats.pending_requests}</div><div class="stat-label">Requests awaiting you</div><div class="stat-caption">Your next decision</div></div></div></div><div class="section-row"><div><h3>Recommended opportunities</h3><p>Selected from the event records currently available in Campus Connect.</p></div><button class="link-btn" data-nav="discover">View all events →</button></div><div class="event-grid">${events.map(renderEventCard).join('')||emptyBlock('No events yet','Add event records or adjust your filters.','discover')}</div><div class="section-row"><div><h3>Your profile signal</h3><p>Evidence-informed, not a guarantee of future performance.</p></div><button class="link-btn" data-nav="profile">Complete profile →</button></div><div class="grid grid-2"><div class="card score-card"><div class="card-head"><div><h3>Overall Profile Score</h3><p>General ability, project evidence, history and teammate reviews.</p></div><span class="tag teal">Your profile</span></div><div class="score-summary">${scoreRing(profile.score)}<div><h3>${esc(profile.confidence_label||'Provisional score')}</h3><p>${esc(profile.description||'Evidence-informed profile summary.')}</p><span class="tag ${profile.confidence>=60?'green':'orange'}">${profile.confidence||0}% evidence confidence</span></div></div><div class="divider"></div>${renderScoreBreakdown(profile)}<div class="footnote">Possible Deserter reports are not included in this score. Pending accusations do not lower your technical skill assessment.</div></div><div class="card"><div class="card-head"><div><h3>Recent agent activity</h3><p>Actual recorded tool and workflow events.</p></div><span class="tag purple">Orchestrated</span></div><div class="activity-list">${(d.agent_activity||[]).slice(0,6).map(renderActivity).join('')||`<div class="empty-state"><div class="empty-illustration">✦</div><h3>Your agent timeline starts here</h3><p>Run Team Architect or search repositories to see real tool activity recorded here.</p><button class="btn btn-outline btn-sm" data-nav="find-team">Start team matching</button></div>`}</div></div></div><div class="section-row"><div><h3>Your current teams</h3><p>Keep track of your roster, open roles and one designated backup.</p></div><button class="link-btn" data-nav="my-teams">View teams →</button></div><div class="grid grid-2">${(d.teams||[]).slice(0,2).map(renderTeamCard).join('')||emptyBlock('No teams yet','Create a team around an event or apply to an open team.','find-team')}</div>`;}
function renderActivity(a){const symbols={'Scout Agent':'✦','Profile Intelligence Agent':'◉','Team Architect Agent':'♧','Consent & Coordination Agent':'✉','Backup & Recovery Agent':'↻','GitHub Research Agent':'⌘','Trust & Review Agent':'✓','Admin Review':'⚑','Orchestrator':'◇'};const detail=a.details||{};let summary=detail.event_name||detail.candidate_name||detail.summary||detail.reason||detail.message||'';return `<div class="activity-item"><div class="activity-symbol">${symbols[a.agent]||'◇'}</div><div><b>${esc(a.action)}</b><p>${esc(a.agent)}${summary?` · ${esc(summary)}`:''}</p><time>${timeAgo(a.created_at)}</time></div></div>`;}
function renderEventCard(e){const palettes=['','purple-cover','orange-cover','blue-cover'];const idx=(Number(e.id)||0)%4;const status=e.status==='completed'?'<span class="tag">Completed</span>':e.status==='registration_open'?'<span class="tag green">Registration open</span>':'<span class="tag teal">Upcoming</span>';return `<article class="card event-card"><div class="event-cover ${palettes[idx]}"><span class="event-category">${esc(e.category)}</span><span class="event-mark">${idx===1?'✧':idx===2?'♧':idx===3?'⌘':'✦'}</span><div class="cover-orb"></div></div><div class="event-body"><div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px"><h3>${esc(e.name)}</h3>${status}</div><div class="event-meta"><span>⌖ ${esc(e.location||'Location TBC')}</span><span>◷ ${dateFmt(e.event_start,{month:'short',day:'numeric'})}</span><span>♧ Team ${e.min_team_size}–${e.max_team_size}</span></div><p class="event-desc">${esc(e.description)}</p><div class="skill-chips">${(e.required_skills||[]).slice(0,3).map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')}${e.is_demo?'<span class="tag orange">Demo data</span>':''}</div><div class="event-footer"><span class="event-deadline">Deadline · ${dateFmt(e.registration_deadline,{month:'short',day:'numeric'})}</span><button class="btn btn-outline btn-sm" data-action="open-event" data-id="${e.id}">Details ↗</button></div></div></article>`;}
function renderTeamCard(t){const memberAvatars=(t.members||[]).slice(0,5).map(m=>`<div class="avatar" title="${esc(m.name)}">${esc(initials(m.name))}</div>`).join('');const filled=t.primary_count||0,limit=t.primary_limit||1;return `<article class="card team-card"><div class="team-card-top"><div><span class="tag ${t.status==='completed'?'purple':t.status==='recovery_needed'?'orange':'teal'}">${esc(t.status==='recovery_needed'?'Recovery needed':t.status==='completed'?'Completed':'Recruiting')}</span><h3 style="font-family:Manrope,sans-serif;font-size:14px;margin:10px 0 5px">${esc(t.name)}</h3><p style="font-size:10px;color:#8490a3;margin:0">${esc(t.event_name)}</p></div><span class="tag">${filled}/${limit}</span></div><div class="team-avatar-stack">${memberAvatars||'<span class="small-note">No primary members</span>'}</div><div class="team-progress"><span>Primary roster</span><div class="progress"><span style="width:${Math.min(100,filled/limit*100)}%"></span></div><b>${filled}/${limit}</b></div><div class="team-skills"><div class="team-skills-title">Team status</div><div class="skill-chips"><span class="skill-chip">${t.primary_slots_open} primary slot(s) open</span><span class="skill-chip">${t.backup_count?`Backup · ${esc(t.backup.name)}`:'Backup slot open'}</span></div></div><div class="team-foot"><small>${esc(t.location||'')} · ${dateFmt(t.event_start,{month:'short',day:'numeric'})}</small><button class="btn btn-dark btn-sm" data-action="open-team" data-id="${t.id}">Workspace →</button></div></article>`;}
function emptyBlock(title,text,nav){return `<div class="card empty-state"><div class="empty-illustration">✦</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${nav?`<button class="btn btn-outline btn-sm" data-nav="${nav}">Open ${esc(nav==='discover'?'events':nav==='find-team'?'team finder':nav)} →</button>`:''}</div>`;}
function loadingBlock(text){return `<div class="card empty-state"><div class="empty-illustration">◌</div><h3>Loading</h3><p>${esc(text)}</p></div>`;}

function renderDiscover(){if(!state.events.length && state.loading.events)return loadingBlock('Loading event records…');const e=state.events||[];return `<div class="page-heading"><div><div class="eyebrow">FIND YOUR NEXT OPPORTUNITY</div><h2>Discover events</h2><p>Search hackathons by topic, location, and eligibility. Open an event to see team requirements.</p></div><div class="heading-actions"><button class="btn btn-outline" data-action="suggest-event">＋ Suggest an event</button></div></div><div class="data-notice"><b>Data transparency:</b> the supplied events are labelled demo records. This app currently searches its configured event database; live event aggregation requires a source/API integration. Do not treat demo deadlines as real.</div><div class="toolbar"><input class="input" id="event-search" placeholder="Search AI, climate, design…" value="${esc(state.eventFilters.q)}"><input class="input" id="event-location" placeholder="City or 'online'" value="${esc(state.eventFilters.location)}"><select class="select" id="event-category"><option value="all">All categories</option>${['AI / Hackathon','Climate tech','Campus hackathon','Open source','Fintech','Healthtech','Design'].map(c=>`<option ${state.eventFilters.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select class="select" id="event-status"><option value="all">All statuses</option>${['upcoming','registration_open','ongoing','completed','closed','cancelled'].map(s=>`<option value="${s}" ${state.eventFilters.status===s?'selected':''}>${esc(s.replace('_',' '))}</option>`).join('')}</select><button class="btn btn-dark" data-action="filter-events">Search</button></div><div class="event-grid">${e.map(renderEventCard).join('')||emptyBlock('No events match your search','Try a broader keyword, location or category.','find-team')}</div>`;}
function renderFindTeam(){const upcoming=(state.events||[]).filter(e=>!['completed','closed','cancelled'].includes(e.status));return `<div class="page-heading"><div><div class="eyebrow">FROM INTEREST TO COMMITMENT</div><h2>Find your team</h2><p>Create a team for an event, or apply to join an existing group as a primary or backup member.</p></div></div><div class="grid grid-2"><div class="card"><div class="card-head"><div><h3>Start a team</h3><p>You'll be the captain and first primary member.</p></div><span class="tag teal">Team Architect</span></div><form id="create-team-form"><div class="field"><label>Choose an event</label><select id="create-event-id" name="event_id" class="select" required><option value="">Select an event</option>${upcoming.map(e=>`<option value="${e.id}" ${String(state.findEventId)===String(e.id)?'selected':''}>${esc(e.name)} · ${esc(e.location)}</option>`).join('')}</select></div><div class="field"><label>Team name</label><input name="name" class="input" required maxlength="100" placeholder="e.g. Team Nova"></div><div class="field"><label>What do you want to build?</label><textarea name="goal" class="textarea" maxlength="500" placeholder="Describe the project goal and the skills you need…"></textarea></div><button class="btn btn-primary" type="submit">Create team & open workspace →</button></form></div><div class="card"><div class="card-head"><div><h3>How matching works</h3><p>The score is private to the captain's search workflow.</p></div><span class="tag purple">Agentic AI</span></div><div class="activity-list"><div class="activity-item"><div class="activity-symbol">✦</div><div><b>Scout checks the event</b><p>Retrieves source information, team size, roles and deadlines.</p></div></div><div class="activity-item"><div class="activity-symbol">◉</div><div><b>Profile intelligence finds the gaps</b><p>Separates declared skills from available project and collaboration evidence.</p></div></div><div class="activity-item"><div class="activity-symbol">♧</div><div><b>Team Architect ranks compatible candidates</b><p>Whole-team skill coverage, availability, profile evidence and working style.</p></div></div><div class="activity-item"><div class="activity-symbol">↻</div><div><b>Recovery responds to rejection</b><p>Finds alternatives after a no, but the captain approves new invitations.</p></div></div></div></div></div><div class="section-row"><div><h3>Teams looking for members</h3><p>Apply to join as a primary member or as the team's one backup.</p></div><button class="btn btn-outline btn-sm" data-action="refresh-open-teams">Refresh teams ↻</button></div><div class="toolbar"><input class="input" id="open-team-search" placeholder="Search team or event…"><select class="select" id="open-team-event"><option value="">All upcoming events</option>${upcoming.map(e=>`<option value="${e.id}" ${String(state.findEventId)===String(e.id)?'selected':''}>${esc(e.name)}</option>`).join('')}</select><button class="btn btn-dark" data-action="filter-open-teams">Filter</button></div><div class="grid grid-3">${(state.openTeams||[]).map(renderOpenTeamCard).join('')||emptyBlock('No open teams found','Try another event or start a team of your own.','discover')}</div>`;}
function renderOpenTeamCard(t){return `<article class="card team-card"><div class="team-card-top"><div><span class="tag teal">${esc(t.event_name)}</span><h3 style="font-family:Manrope,sans-serif;font-size:14px;margin:11px 0 5px">${esc(t.name)}</h3><p style="font-size:10px;color:#8490a3;margin:0">Captain · ${esc(t.captain_name)}</p></div></div><p style="font-size:10px;color:#748198;line-height:1.6;margin:13px 0">${esc(t.goal||'Looking for motivated people with complementary skills.')}</p><div class="team-progress"><span>${t.primary_slots_available_to_request} primary spot(s)</span><div class="progress"><span style="width:${Math.max(0,Math.min(100,t.primary_count/t.primary_limit*100))}%"></span></div></div><div class="skill-chips"><span class="skill-chip">${t.backup_slot_available?'Backup slot open':'Backup slot filled'}</span><span class="skill-chip">${esc(t.location||'Online')}</span></div><div class="team-foot"><small>${t.primary_count}/${t.primary_limit} primary members<br>${dateFmt(t.event_start,{month:'short',day:'numeric'})}</small><button class="btn btn-dark btn-sm" data-action="open-team" data-id="${t.id}">View team →</button></div></article>`;}
function renderMyTeams(){return `<div class="page-heading"><div><div class="eyebrow">YOUR COLLABORATIONS</div><h2>My teams</h2><p>Primary roster, backup status, pending invitations and team preparation.</p></div><button class="btn btn-primary" data-nav="find-team">＋ Start a team</button></div><div class="grid grid-2">${(state.teams||[]).map(renderTeamCard).join('')||emptyBlock('No teams yet','Create a team or browse groups looking for teammates.','find-team')}</div>`;}

function renderTeamDetail(){const d=state.currentTeam;if(!d)return loadingBlock('Loading team workspace…');const t=d.team,event=d.event, members=d.members||[], primary=members.filter(m=>m.role==='primary'), backups=members.filter(m=>m.role==='backup'), isCaptain=d.can_manage, isMember=!!d.viewer_membership;const result=state.matchResult;const roleLabel=state.matchRole==='backup'?'backup':'primary';const activeCandidates=result?.candidates||[];const canRecruit=event.status!=='completed'&&event.status!=='closed'&&t.status!=='completed';return `<div class="page-heading"><div><div class="eyebrow">TEAM WORKSPACE</div><h2>${esc(t.name)}</h2><p>${esc(event.name)} · ${esc(event.location)} · Event date ${dateFmt(event.event_start)}</p></div><div class="heading-actions"><button class="btn btn-outline" data-nav="my-teams">← My teams</button><button class="btn btn-outline" data-nav="github">Research GitHub ↗</button>${isCaptain&&canRecruit?`<button class="btn btn-primary" data-action="run-match" data-role="primary" ${t.primary_slots_available_to_request<=0?'disabled':''}>Find primary members ✦</button>`:''}</div></div><div class="team-header"><div><span class="tag ${t.status==='recovery_needed'?'orange':t.status==='completed'?'purple':'teal'}">${esc(t.status==='recovery_needed'?'Recovery needed':t.status==='completed'?'Completed':'Recruiting')}</span>${event.is_demo?'<span class="tag orange">Demo event</span>':''}<h2>${esc(t.name)}</h2><p>${esc(t.goal||'Build a balanced team with clear commitments and complementary skills.')}</p><p style="margin-top:8px">Captain · ${esc(t.captain_name)} &nbsp;·&nbsp; ${t.primary_count}/${t.primary_limit} primary members</p></div><div class="heading-actions">${isCaptain&&canRecruit?`<button class="btn btn-outline" data-action="run-match" data-role="backup" ${!t.backup_slot_available?'disabled':''}>Find one backup ↻</button>`:''}${isMember&&!isCaptain&&canRecruit?`<button class="btn btn-outline" data-action="withdraw-team" data-id="${t.id}">Withdraw from team</button>`:''}</div></div>
<div class="grid grid-2"><div class="card"><div class="card-head"><div><h3>Confirmed primary roster</h3><p>Only accepted, eligible members count towards the team size.</p></div><span class="tag teal">${primary.length}/${t.primary_limit}</span></div><div class="roster-list">${primary.map(m=>`<div class="roster-member"><div class="avatar">${esc(initials(m.profile.name))}</div><div class="roster-member-info"><b>${esc(m.profile.name)} ${m.user_id===t.captain_id?'<span class="tag purple">Captain</span>':''}</b><small>${esc(m.role_label||'Primary member')} · ${esc(m.profile.college||'College not listed')}</small><div class="roster-skill">${(m.profile.skills||[]).slice(0,5).map(s=>esc(s)).join(' · ')||'No skills added yet'}</div></div><div style="text-align:right"><span class="tag">Profile ${m.profile.overall_profile_score.score}/100</span><br><button class="link-btn" style="font-size:9px" data-action="view-profile" data-id="${m.user_id}">View profile</button></div></div>`).join('')||'<div class="small-note">No primary members.</div>'}</div></div><div class="card"><div class="card-head"><div><h3>One-backup protection</h3><p>Exactly one designated backup can exist at a time.</p></div><span class="tag ${backups.length?'orange':'green'}">${backups.length?'1 / 1 slot used':'Slot available'}</span></div>${backups.length?backups.map(m=>`<div class="roster-member"><div class="avatar" style="background:linear-gradient(140deg,#f4b563,#e88671)">${esc(initials(m.profile.name))}</div><div class="roster-member-info"><b>${esc(m.profile.name)} <span class="tag orange">Backup</span></b><small>${esc(m.role_label||'Designated reserve')} · not counted as primary</small><div class="roster-skill">${(m.profile.skills||[]).slice(0,5).map(s=>esc(s)).join(' · ')||'No skills added yet'}</div></div><span class="tag">Score ${m.profile.overall_profile_score.score}</span></div>`).join(''):`<div class="empty-state" style="padding:22px 10px"><div class="empty-illustration">↻</div><h3>No designated backup yet</h3><p>A backup may help the team recover if a primary member withdraws. Check the event's substitute rules first.</p>${isCaptain&&canRecruit?`<button class="btn btn-soft btn-sm" data-action="run-match" data-role="backup">Find a backup →</button>`:''}</div>`}${isCaptain&&canRecruit&&backups.length&&t.primary_slots_open>0?`<div class="divider"></div><div class="warning-panel"><strong>Primary vacancy detected</strong>A captain can request to promote the backup, or search for another primary member. Promotion requires the backup's acceptance.</div><button class="btn btn-primary btn-sm" data-action="promote-backup" data-id="${t.id}">Request backup promotion →</button><button class="btn btn-outline btn-sm" data-action="run-match" data-role="primary" style="margin-left:6px">Find replacement</button>`:''}<div class="footnote">The backup is a reserve role in Campus Connect, not proof that the event organiser officially permits substitutes.</div></div></div>
${isCaptain?renderCaptainRequests(d.pending_requests||[]):''}
${isCaptain&&canRecruit?`<div class="section-row"><div><h3>Team Architect</h3><p>Run an actual tool-using search. Compatibility scores below are private to you as captain and will not appear on candidates' own profiles.</p></div><span class="tag purple">Agentic workflow</span></div><div class="card"><div class="toolbar"><button class="filter-pill ${state.matchRole==='primary'?'active':''}" data-action="set-match-role" data-role="primary">Find primary members</button><button class="filter-pill ${state.matchRole==='backup'?'active':''}" data-action="set-match-role" data-role="backup">Find one backup</button><button class="btn btn-dark" data-action="run-match" data-role="${roleLabel}" ${(roleLabel==='primary'?t.primary_slots_available_to_request<=0:!t.backup_slot_available)?'disabled':''}>Run Team Architect ✦</button></div><div id="matching-results">${result?renderMatchingResults(result,roleLabel):`<div class="empty-state"><div class="empty-illustration">♧</div><h3>Let the agents find the missing pieces</h3><p>Scout checks requirements, Profile Intelligence identifies gaps, and Team Architect ranks suitable candidates. New invitations remain under your control.</p></div>`}</div></div>`:''}
<div class="section-row"><div><h3>Team preparation</h3><p>A lightweight checklist for moving from a formed team to an actual submission.</p></div><span class="tag blue">Activation Agent</span></div><div class="card"><div class="grid grid-2"><div><h3 style="font-size:12px;margin:0 0 7px">Event checklist</h3><p class="small-note">Use this workspace to align the team's next steps. Suggested roles and tasks should be reviewed by members.</p><div class="skill-chips"><span class="skill-chip">Confirm project idea</span><span class="skill-chip">Plan MVP</span><span class="skill-chip">Agree role ownership</span><span class="skill-chip">Review official registration</span></div></div><div><div class="team-progress" style="margin:4px 0 14px"><span>Primary team filled</span><div class="progress"><span style="width:${Math.min(100,primary.length/t.primary_limit*100)}%"></span></div><b>${Math.round(primary.length/t.primary_limit*100)}%</b></div><div class="small-note">Registration deadline: <b>${dateFmt(event.registration_deadline)}</b><br>${event.registration_url?`<a class="text-btn" href="${esc(event.registration_url)}" target="_blank" rel="noopener">Open official registration ↗</a>`:'No verified registration URL is configured for this demo record.'}</div></div></div></div>
${d.can_review?renderReviewSection(d):''}`;}
function renderCaptainRequests(requests){if(!requests.length)return '';return `<div class="section-row"><div><h3>Pending requests</h3><p>Review applications and track your outstanding invitations.</p></div><span class="tag orange">${requests.length} pending</span></div><div class="card">${requests.map(r=>`<div class="request-row"><div class="avatar small">${esc(initials(r.other_name))}</div><div class="request-row-main"><b>${esc(r.other_name)} · ${esc(r.role.replace('promote_backup','promotion'))}</b><p>${esc(r.kind==='application'?'Applied to join your team':r.kind==='promotion'?'Backup promotion request':'Invitation sent')} · ${esc(r.other_college||'')} · ${esc(r.other_city||'')}${r.message?`<br>${esc(r.message)}`:''}</p></div><div class="request-actions">${r.kind==='application'&&r.incoming?`<button class="btn btn-primary btn-sm" data-action="respond-request" data-id="${r.request_id}" data-choice="accept">Accept</button><button class="btn btn-outline btn-sm" data-action="respond-request" data-id="${r.request_id}" data-choice="decline">Decline</button>`:`<span class="tag">Awaiting ${r.kind==='promotion'?'backup':'candidate'}</span>`}</div></div>`).join('')}</div>`;}
function renderMatchingResults(result,role){
 const candidates=result.candidates||[];
 if(!candidates.length)return `<div class="empty-state"><div class="empty-illustration">⌕</div><h3>No eligible candidates found</h3><p>The agent did not invent candidates. Try broadening location or availability, or invite interested students to opt into discovery.</p></div>`;
 const maxInvite=Math.max(0,Math.min(Number(result.invite_limit??(role==='backup'?1:candidates.length)),candidates.length));
 const suggestedIds=Array.isArray(result.suggested_candidate_ids)?result.suggested_candidate_ids.slice(0,maxInvite):candidates.slice(0,maxInvite).map(c=>(c.user||c).id);
 const byId=new Map(candidates.map(c=>{const u=c.user||c;return [Number(u.id),u]}));
 const suggestedNames=suggestedIds.map(id=>byId.get(Number(id))?.name).filter(Boolean);
 const provider=result.llm_provider|| (result.llm_configured?'configured LLM':'deterministic');
 const groupPanel=`<div class="suggested-team-panel"><div class="suggested-team-heading"><div><span class="eyebrow">TEAM ARCHITECT RECOMMENDATION</span><h3>Suggested ${role==='backup'?'backup':'team members'}</h3><p>${role==='backup'?'The top eligible candidate for your one backup slot.':'Top candidates selected to fill the currently available primary slots.'} Each person still must accept individually.</p></div>${suggestedIds.length?`<button class="btn btn-primary" data-action="invite-all-suggested" data-role="${esc(role)}" data-run="${Number(result.run_id||0)}">Invite all suggested (${suggestedIds.length}) →</button>`:`<span class="tag orange">No invite slots available</span>`}</div><div class="suggested-name-list">${suggestedNames.map((name,i)=>`<span class="suggested-name"><span>${i+1}</span>${esc(name)}</span>`).join('')||'<span class="small-note">No suggested invite group is available. Refresh Team Architect after resolving pending requests.</span>'}</div><p class="footnote">The button sends invitations to this suggested set in one captain action. It does not automatically add anyone to the roster.</p></div>`;
 return `<div class="data-notice"><b>Run #${result.run_id||'—'}:</b> ${esc(result.summary||'Shortlist generated by tool-using agents.')}<br>Missing skill signals: ${esc((result.missing_skills||[]).join(', ')||'None detected')}. ${result.llm_configured?`${esc(provider)} tool-use review enabled.`:'Deterministic tool workflow; add SARVAM_API_KEY and AI_PROVIDER=sarvam for optional Sarvam AI review.'}</div>${groupPanel}<div class="section-row"><div><h3>All candidate options</h3><p>Invite individuals below if you want to choose a different combination.</p></div></div><div class="candidate-list">${candidates.map((c,i)=>{const u=c.user||c;const comp=c.compatibility||{};const warns=c.warnings||[];const suggested=suggestedIds.includes(Number(u.id));return `<article class="candidate-card"><div class="candidate-main"><div class="candidate-heading"><div class="avatar">${esc(initials(u.name))}</div><div><h4>${esc(u.name)} ${u.is_demo?'<span class="tag orange">Demo profile</span>':''} ${suggested?'<span class="tag teal">Suggested pick</span>':''}</h4><p>${esc(u.college||'College not listed')} · ${esc(u.city||'Location not listed')}</p></div></div><div class="score-pair"><span class="score-pill">Overall Profile Score <b>${u.profile_score?.score??'—'}/100</b></span><span class="score-pill">Evidence confidence <b>${u.profile_score?.confidence??0}%</b></span>${c.interested_in_event?'<span class="tag green">Interested in event</span>':''}${c.saved_event?'<span class="tag blue">Saved event</span>':''}</div><div class="skill-chips">${(u.skills||[]).slice(0,6).map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')}</div><p class="candidate-bio">${esc(u.bio||'No bio added yet.')} <span style="color:#98a3b4">${esc(u.profile_goal||'')}</span></p>${warns.map(w=>`<div class="candidate-warning"><b>${esc(w.label)}</b> · ${esc(w.event)} · ${esc(w.explanation)}</div>`).join('')}<div class="candidate-actions"><button class="btn btn-outline btn-sm" data-action="view-profile" data-id="${u.id}">View profile evidence</button><button class="btn btn-ghost btn-sm" data-action="toggle-candidate-detail" data-id="${u.id}">Why this match?</button></div><div class="candidate-detail" id="candidate-detail-${u.id}">${(comp.components||[]).map(k=>`<div class="score-line"><label>${esc(k.label)} <span style="color:#a2adbd">${k.weight}%</span></label><div class="progress ${k.key==='overall_profile'?'purple':''}"><span style="width:${k.score}%"></span></div><b>${k.score}</b></div><p class="small-note">${esc(k.explanation||'')}</p>`).join('')}${comp.reliability_adjustment?`<p class="candidate-warning">A bounded ${comp.reliability_adjustment}-point adjustment reflects an upheld no-show case, not an unreviewed report.</p>`:''}<p class="footnote">${esc(comp.explanation||'')} Candidate skills and history remain subject to the evidence labels shown on their profile.</p></div></div><div class="candidate-score"><strong>${comp.score??'—'}</strong><small>TEAM COMPATIBILITY<br>captain-only</small><span class="tag ${comp.score>=80?'green':comp.score>=65?'teal':'orange'}">${comp.score>=80?'Strong fit':comp.score>=65?'Potential fit':'Review fit'}</span><div style="margin-top:12px"><button class="btn btn-primary btn-sm" data-action="invite-candidate" data-id="${u.id}" data-role="${esc(role)}">Invite as ${esc(role)}</button></div></div></article>`;}).join('')}</div><p class="footnote">Compatibility scores are event/team-specific prototype heuristics. They are shown to this captain's agent workflow only, never on candidates' own profiles or application screens. The captain must verify event eligibility and confirm commitments before inviting.</p>`;
}
function renderReviewSection(d){const members=d.reviewables||[];return `<div class="section-row"><div><h3>Post-event teammate review</h3><p>Review collaboration honestly. A no-show report is separate from a poor performance rating.</p></div><span class="tag purple">Trust & review</span></div><div class="card"><div class="data-notice">Only confirmed teammates can review one another after this event. The Possible Deserter tag requires multiple eligible reports; one unverified complaint never creates the tag.</div>${members.map(m=>`<div class="review-card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><h4>${esc(m.name)}</h4><p class="small-note">${m.already_reviewed?'You have already reviewed this teammate. You may still submit a separate no-show report if appropriate.':'Rate the collaboration based on what you observed.'}</p></div>${m.already_reviewed?'<span class="tag green">Reviewed</span>':''}</div>${!m.already_reviewed?`<form data-form="review" data-team="${d.team.id}" data-target="${m.user_id}"><div class="rating-grid">${[['contribution','Contribution'],['reliability','Reliability'],['teamwork','Teamwork'],['communication','Communication'],['role_fulfilment','Role fulfilment']].map(([k,l])=>`<div class="field"><label>${l}</label><select name="${k}" required><option value="5">5 · Strong</option><option value="4" selected>4 · Good</option><option value="3">3 · Mixed</option><option value="2">2 · Weak</option><option value="1">1 · Poor</option></select></div>`).join('')}</div><div class="field"><label>Optional factual comment</label><textarea name="comment" class="textarea" placeholder="What did they contribute? Keep feedback specific and respectful."></textarea></div><button class="btn btn-primary btn-sm" type="submit">Submit review</button></form>`:''}<div style="margin-top:12px"><button class="btn btn-danger btn-sm" data-action="report-deserter" data-id="${m.user_id}" data-team="${d.team.id}" ${m.already_reported?'disabled':''}>⚑ ${m.already_reported?'No-show report submitted':'Report a possible no-show'}</button></div></div>`).join('')}</div>`;}

function renderInbox(){const d=state.inbox;if(!d)return loadingBlock('Loading inbox…');const msgs=d.messages||[];return `<div class="page-heading"><div><div class="eyebrow">A SINGLE PLACE FOR TEAM DECISIONS</div><h2>Inbox</h2><p>Invitations, responses, backup requests, recovery suggestions, and platform updates.</p></div><div class="heading-actions"><span class="tag ${d.unread_count?'teal':''}">${d.unread_count} unread</span><button class="btn btn-outline" data-action="read-all">Mark all read</button></div></div><div class="inbox-list">${msgs.map(m=>renderInboxRow(m)).join('')||emptyBlock('Your inbox is clear','Team invitations and updates will appear here.','find-team')}</div>`;}
function renderInboxRow(m){const icons={team_invitation:'✉',team_application:'♧',backup_promotion:'↻',recovery_shortlist:'⚡',member_withdrawal:'↘',deserter_case:'⚑',deserter_case_update:'✓',request_update:'✓',system:'✦',event_proposal:'＋',event_proposal_update:'✓',admin_review:'⚑'};const data=m.data||{};const actionable=['team_invitation','team_application','backup_promotion'].includes(m.type)&&data.request_id;let actions='';if(actionable){actions=`<button class="btn btn-primary btn-sm" data-action="respond-request" data-id="${data.request_id}" data-choice="accept">Accept</button><button class="btn btn-outline btn-sm" data-action="respond-request" data-id="${data.request_id}" data-choice="decline">Decline</button>`;}else if(m.type==='recovery_shortlist'&&data.team_id){actions=`<button class="btn btn-soft btn-sm" data-action="open-recovery" data-team="${data.team_id}" data-run="${data.run_id||''}">Review candidates →</button>`;}else if(m.type==='deserter_case'){actions=`<button class="btn btn-outline btn-sm" data-action="respond-case-view">Respond / dispute</button>`;}else if(m.type==='admin_review'&&data.case_id&&state.user.is_admin){actions=`<button class="btn btn-outline btn-sm" data-nav="admin">Review case →</button>`;}return `<article class="inbox-row ${m.is_read?'':'unread'}"><div class="inbox-icon">${icons[m.type]||'✦'}</div><div><h4>${esc(m.title)}</h4><p>${esc(m.body)}</p><time>${m.sender_name?`From ${esc(m.sender_name)} · `:''}${timeAgo(m.created_at)}</time>${m.type==='recovery_shortlist'&&data.run_id?`<div class="footnote">Agent shortlist · run #${data.run_id}</div>`:''}</div><div class="inbox-actions">${actions}${!m.is_read?`<button class="btn btn-ghost btn-sm" data-action="read-message" data-id="${m.id}">Mark read</button>`:''}</div></article>`;}

function renderProfile(){const p=state.user;if(!p)return loadingBlock('Loading profile…');const score=p.overall_profile_score||{score:0,components:[]};return `<div class="page-heading"><div><div class="eyebrow">YOUR SKILLS, PROJECTS & COLLABORATION</div><h2>My profile</h2><p>The Overall Profile Score summarizes available evidence. There is no global compatibility score on your profile.</p></div><button class="btn btn-primary" data-action="save-profile" form="profile-form">Save changes ✓</button></div><div class="profile-layout"><div><div class="card profile-identity"> <div class="avatar">${esc(initials(p.name))}</div><h3>${esc(p.name)}</h3><p>${esc(p.course||'Student')} · ${esc(p.college||'College not added')}</p><div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap"><span class="tag teal">Profile score ${score.score}/100</span>${p.is_demo?'<span class="tag orange">Demo profile</span>':''}</div><div class="profile-meta"><div>⌖ <span><strong>Location</strong><br>${esc(p.city||'Not specified')}</span></div><div>◷ <span><strong>Availability</strong><br>${esc((p.availability||[]).join(', ')||'Not specified')}</span></div><div>✦ <span><strong>Discoverable</strong><br>${p.discoverable?'Visible to matching agents':'Hidden from teammate search'}</span></div><div>⌘ <span><strong>GitHub</strong><br>${p.github_username?`@${esc(p.github_username)}`:'Not connected'}</span></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Overall Profile Score</h3><p>General capabilities and evidence.</p></div></div><div class="score-summary">${scoreRing(score.score)}<div><h3>${esc(score.confidence_label||'Provisional')}</h3><p>${esc(score.description||'')} </p><span class="tag ${score.confidence>=60?'green':'orange'}">${score.confidence||0}% confidence</span></div></div><div class="divider"></div>${renderScoreBreakdown(score)}<div class="footnote">Missing evidence is unknown, not automatically bad. The score does not include raw Possible Deserter allegations. GitHub and LinkedIn links are not proof of skill by themselves.</div></div>${(p.deserter_tags||[]).length?`<div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Team reliability notices</h3><p>Event-specific warning, not a technical-skill judgement.</p></div></div>${p.deserter_tags.map(tag=>`<div class="tag-card"><h4>⚑ ${esc(tag.label)} · ${esc(tag.event)}</h4><p>${esc(tag.explanation)} Reports: ${tag.report_count}/${tag.required_threshold}. Status: ${esc(tag.status)}.</p>${!tag.has_responded&&['pending','disputed'].includes(tag.status)?`<textarea id="case-response-${tag.case_id}" placeholder="Share context or dispute an inaccurate report (minimum 10 characters)"></textarea><button class="btn btn-outline btn-sm" style="margin-top:8px" data-action="respond-case" data-id="${tag.case_id}">Submit response</button>`:''}</div>`).join('')}</div>`:''}</div><div><form id="profile-form" class="card"><div class="card-head"><div><h3>Profile details</h3><p>Only information you choose to provide is shared. Review AI-extracted fields before saving.</p></div><span class="tag blue">Editable</span></div><div class="form-grid"><div class="field"><label>Display name</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>College</label><input name="college" value="${esc(p.college||'')}"></div><div class="field"><label>Course / field</label><input name="course" value="${esc(p.course||'')}"></div><div class="field"><label>Year of study</label><input name="year" value="${esc(p.year||'')}"></div><div class="field"><label>City</label><input name="city" value="${esc(p.city||'')}"></div><div class="field"><label>Preferred participation</label><select name="preferred_mode"><option ${p.preferred_mode==='Either'?'selected':''}>Either</option><option ${p.preferred_mode==='In person'?'selected':''}>In person</option><option ${p.preferred_mode==='Online'?'selected':''}>Online</option><option ${p.preferred_mode==='Hybrid'?'selected':''}>Hybrid</option></select></div><div class="field"><label>Travel radius (km)</label><input type="number" name="travel_radius" min="0" max="1000" value="${Number(p.travel_radius||25)}"></div><div class="field"><label>Availability (comma-separated)</label><input name="availability" value="${esc((p.availability||[]).join(', '))}" placeholder="weekends, evenings"></div><div class="field span-full"><label>Short bio</label><textarea name="bio" class="textarea" maxlength="500">${esc(p.bio||'')}</textarea></div><div class="field span-full"><label>Skills (comma-separated)</label><input name="skills" value="${esc((p.skills||[]).join(', '))}" placeholder="Frontend, Python, AI/ML"><span class="input-hint">Claims are self-declared until supported by evidence. Wanting to learn a skill is not the same as claiming proficiency.</span></div><div class="field span-full"><label>Interests (comma-separated)</label><input name="interests" value="${esc((p.interests||[]).join(', '))}" placeholder="AI, education, climate tech"></div><div class="field span-full"><label>Preferred roles (comma-separated)</label><input name="roles" value="${esc((p.roles||[]).join(', '))}" placeholder="Backend, research, pitch lead"></div><div class="field span-full"><label>Working preferences (comma-separated)</label><input name="work_preferences" value="${esc((p.work_preferences||[]).join(', '))}" placeholder="Collaborative, async updates, clear milestones"></div><div class="field span-full"><label>Collaboration / project goal</label><textarea name="profile_goal" class="textarea" maxlength="500" placeholder="What would you like to contribute or learn?">${esc(p.profile_goal||'')}</textarea></div><div class="field"><label>GitHub username</label><input name="github_username" value="${esc(p.github_username||'')}" placeholder="username"></div><div class="field"><label>GitHub profile URL (optional)</label><input name="github_url" value="${esc(p.github_url||'')}" placeholder="https://github.com/username"></div><div class="field"><label>LinkedIn profile URL</label><input name="linkedin_url" value="${esc(p.linkedin_url||'')}" placeholder="https://linkedin.com/in/…"><span class="input-hint">Campus Connect does not scrape LinkedIn automatically. A link alone does not add score points.</span></div><div class="field"><label>Portfolio URL</label><input name="portfolio_url" value="${esc(p.portfolio_url||'')}" placeholder="https://…"></div><div class="field span-full"><label>Projects (one per line: Name | URL | what you contributed)</label><textarea name="projects" class="textarea" style="min-height:95px" placeholder="Campus helper | https://… | Built React dashboard">${esc(linesFor(p.projects,'project'))}</textarea><span class="input-hint">Saved as self-reported/evidence-linked entries. Linking a repository does not automatically verify authorship or proficiency.</span></div><div class="field span-full"><label>Past hackathons (one per line: Event | outcome | evidence URL)</label><textarea name="hackathons" class="textarea" style="min-height:85px" placeholder="Student Hack Day | Participated | https://…">${esc(linesFor(p.hackathons,'hackathon'))}</textarea><span class="input-hint">Claims remain self-reported unless independently corroborated.</span></div><div class="field span-full"><label style="display:flex;gap:9px;align-items:center"><input type="checkbox" name="discoverable" ${p.discoverable?'checked':''} style="width:auto"> Let eligible matching agents discover my profile</label></div><div class="field span-full"><label for="notification-preference">Notification delivery</label><select id="notification-preference" name="notification_preference"><option value="in_app" ${(p.notification_preference||'in_app')==='in_app'?'selected':''}>Campus Connect inbox only</option><option value="in_app_email" ${p.notification_preference==='in_app_email'?'selected':''}>Campus Connect inbox + email</option></select><span class="input-hint">Messages always appear in the in-app inbox. Email delivery works only when the platform administrator configures SMTP; your selection is saved either way.</span></div></div><div class="heading-actions" style="margin-top:12px"><button class="btn btn-primary" type="submit">Save profile ✓</button></div><div class="footnote">Public GitHub evidence is refreshed automatically on profile save when the username is new or the cached snapshot is older than 30 days. Add either a GitHub username or a github.com profile URL. If GitHub is unavailable, your profile still saves. LinkedIn is not scraped; a link alone is not verified evidence.</div></form></div></div>`;}

function renderGithub(){const results=state.githubResults;return `<div class="page-heading"><div><div class="eyebrow">RESEARCH BEFORE YOU REBUILD</div><h2>GitHub research</h2><p>Find starter projects, examples and technical references related to your event or project idea.</p></div><span class="tag purple">GitHub Research Agent</span></div><section class="github-search-hero"><h2>Find a useful starting point.</h2><p>Describe the problem, framework or technical feature. The agent queries GitHub's repository search API when reachable and labels any offline fallback clearly.</p><form class="github-search-form" id="github-search-form"><input id="github-query" required minlength="2" value="${esc(state.githubQuery||'agentic AI team matching')}" placeholder="e.g. FastAPI agent orchestration, React dashboard…"><input id="github-language" style="max-width:150px;flex:0 0 150px" placeholder="Language (optional)"><button class="btn btn-primary" type="submit">Search repositories ↗</button></form></section><div class="data-notice">Recommendations are based on retrieved repository metadata, not an assertion that a project is safe or ready to reuse. Check README, dependencies, recent activity and licensing before using code.</div>${results?`<div class="section-row"><div><h3>${results.repositories.length} repository suggestions</h3><p>Query: “${esc(results.query)}” · Source: ${esc(results.source)}</p></div><span class="tag ${results.live?'green':'orange'}">${results.live?'Live API results':'Offline fallback'}</span></div><div class="grid grid-2">${results.repositories.map(renderRepoCard).join('')}</div><p class="footnote">${esc(results.notice||'')} Result descriptions and popularity metadata can change. Review source repositories directly.</p>`:emptyBlock('Search repositories','Try a project idea or technology to find relevant starter code and examples.','discover')}`;}
function renderRepoCard(r){return `<article class="repo-card"><div class="repo-top"><div class="repo-glyph">⌘</div><div><h3><a href="${esc(r.html_url)}" target="_blank" rel="noopener">${esc(r.full_name||r.name)} ↗</a></h3><p>${esc(r.language||'Language not specified')} ${r.license?`· ${esc(r.license)} licence`:''}</p></div></div><p class="repo-desc">${esc(r.description||'No repository description is available.')}</p><div class="repo-meta">${r.stars!==undefined?`<span>★ ${Number(r.stars).toLocaleString()}</span>`:''}${r.updated_at?`<span>Updated ${dateFmt(r.updated_at,{month:'short',year:'numeric'})}</span>`:''}${r.fork?'<span>Fork</span>':''}${(r.topics||[]).slice(0,3).map(t=>`<span>#${esc(t)}</span>`).join('')}</div><div class="repo-why"><b>Why it may help:</b> ${esc(r.why_relevant||r.match_hint||'Related to the search query. Review the README to confirm fit.')}</div><div class="repo-footer"><span class="tag ${r.source==='GitHub public API'?'green':'orange'}">${esc(r.source||'Retrieved repo')}</span><a class="btn btn-outline btn-sm" href="${esc(r.html_url)}" target="_blank" rel="noopener">Open repository ↗</a></div></article>`;}

function renderAdmin(){const d=state.adminData;if(!d)return loadingBlock('Loading trust and administration…');return `<div class="page-heading"><div><div class="eyebrow">PLATFORM OPERATIONS</div><h2>Admin & trust</h2><p>Manage event data and review disputed no-show reports. Decisions must be evidence-informed.</p></div><span class="tag purple">Admin access</span></div><div class="grid grid-4"><div class="stat-card"><div class="stat-icon teal">◉</div><div><div class="stat-value">${d.overview.users}</div><div class="stat-label">Accounts</div></div></div><div class="stat-card"><div class="stat-icon purple">✦</div><div><div class="stat-value">${d.overview.events}</div><div class="stat-label">Event records</div></div></div><div class="stat-card"><div class="stat-icon orange">♧</div><div><div class="stat-value">${d.overview.teams}</div><div class="stat-label">Teams</div></div></div><div class="stat-card"><div class="stat-icon blue">⚑</div><div><div class="stat-value">${d.overview.pending_cases}</div><div class="stat-label">Trust cases to review</div></div></div></div><div class="section-row"><div><h3>Add an event record</h3><p>Use official sources where possible; the record will be labelled with its source.</p></div></div><div class="card"><form id="admin-event-form"><div class="form-grid"><div class="field"><label>Event name</label><input name="name" required></div><div class="field"><label>Organiser</label><input name="organizer" required></div><div class="field"><label>Category</label><input name="category" value="Hackathon"></div><div class="field"><label>Format</label><select name="mode"><option>In person</option><option>Online</option><option>Hybrid</option></select></div><div class="field"><label>Location</label><input name="location" value="Chennai"></div><div class="field"><label>Required skills (comma-separated)</label><input name="required_skills" placeholder="Frontend, Backend, AI/ML"></div><div class="field"><label>Start date</label><input name="event_start" type="date" required></div><div class="field"><label>End date</label><input name="event_end" type="date" required></div><div class="field"><label>Registration deadline</label><input name="registration_deadline" type="date" required></div><div class="field"><label>Minimum / maximum team size</label><div style="display:flex;gap:8px"><input name="min_team_size" class="input" type="number" min="1" max="20" value="2" required><input name="max_team_size" class="input" type="number" min="1" max="20" value="4" required></div></div><div class="field"><label>Official event URL</label><input name="source_url" type="url" placeholder="https://…"></div><div class="field"><label>Registration URL</label><input name="registration_url" type="url" placeholder="https://…"></div><div class="field span-full"><label>Description</label><textarea name="description" class="textarea"></textarea></div><div class="field span-full"><label>Eligibility</label><input name="eligibility" value="Open to college students"></div></div><button class="btn btn-primary" type="submit">Save event record ✓</button></form></div><div class="section-row"><div><h3>Add and customise people</h3><p>Create additional candidate accounts with profile information for real matching. Each account can later sign in and edit their own profile.</p></div><span class="tag blue">${(d.people||[]).length} profiles</span></div><div class="card"><form id="admin-person-form"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" minlength="2" maxlength="80" required placeholder="Candidate name"></div><div class="field"><label>Login email</label><input name="email" type="email" required placeholder="person@college.edu"></div><div class="field"><label>Initial password (8+ characters)</label><input name="password" type="password" minlength="8" required autocomplete="new-password"></div><div class="field"><label>College</label><input name="college" placeholder="College / institution"></div><div class="field"><label>Course / field</label><input name="course" placeholder="Computer Science"></div><div class="field"><label>Year of study</label><input name="year" placeholder="2nd year"></div><div class="field"><label>City</label><input name="city" value="Chennai"></div><div class="field"><label>Skills (comma-separated)</label><input name="skills" placeholder="Backend, Python, APIs"></div><div class="field"><label>Interests (comma-separated)</label><input name="interests" placeholder="AI, education, climate tech"></div><div class="field"><label>Preferred roles (comma-separated)</label><input name="roles" placeholder="Backend, researcher"></div><div class="field"><label>Availability (comma-separated)</label><input name="availability" value="weekends, evenings"></div><div class="field"><label>Working preferences (comma-separated)</label><input name="work_preferences" value="collaborative, clear milestones"></div><div class="field"><label>GitHub username (optional)</label><input name="github_username" placeholder="username"></div><div class="field"><label>GitHub profile URL</label><input name="github_url" type="url" placeholder="https://github.com/username"></div><div class="field"><label>LinkedIn profile URL</label><input name="linkedin_url" type="url" placeholder="https://linkedin.com/in/…"></div><div class="field"><label>Portfolio URL</label><input name="portfolio_url" type="url" placeholder="https://…"></div><div class="field span-full"><label>Short bio</label><textarea class="textarea" name="bio" maxlength="500" placeholder="What they enjoy building and what they can contribute"></textarea></div><div class="field span-full"><label>Collaboration goal</label><textarea class="textarea" name="profile_goal" maxlength="500" placeholder="What kind of team or project do they want?"></textarea></div><div class="field span-full"><label>Projects (one per line: Name | URL | contribution)</label><textarea class="textarea" name="projects" placeholder="API starter | https://github.com/... | Built endpoints"></textarea></div><div class="field span-full"><label>Past hackathons (one per line: Event | outcome | evidence URL)</label><textarea class="textarea" name="hackathons" placeholder="Campus hackathon | Participated | https://..."></textarea></div><div class="field span-full"><label style="display:flex;gap:9px;align-items:center"><input type="checkbox" name="discoverable" checked style="width:auto"> Allow this profile to be found by matching agents</label></div></div><button class="btn btn-primary" type="submit">Create candidate account + profile →</button><p class="footnote">The email and password are login credentials for the person you create. Share them privately. In production, users should change any temporary password after signing in.</p></form></div><div class="grid grid-3">${(d.people||[]).slice(0,30).map(renderAdminPerson).join('')}</div><div class="section-row"><div><h3>Possible-deserter cases</h3><p>Unreviewed reports are warnings, not findings. Review the context and the reported person's response.</p></div><span class="tag orange">${d.cases.length} case(s)</span></div>${d.cases.map(renderAdminCase).join('')||emptyBlock('No trust cases','A case appears when reports need review.','profile')}<div class="section-row"><div><h3>Suggested events</h3><p>Students can submit event links for review.</p></div></div><div class="card">${(d.proposals||[]).map(p=>`<div class="request-row"><div class="request-row-main"><b>${esc(p.name)} <span class="tag">${esc(p.status)}</span></b><p>${esc(p.proposer_name)} · ${esc(p.reason||'No note')}${p.url?`<br><a class="text-btn" href="${esc(p.url)}" target="_blank" rel="noopener">Open source ↗</a>`:''}</p></div>${p.status==='pending'?`<button class="btn btn-outline btn-sm" data-action="accept-proposal" data-id="${p.id}">Mark reviewed</button>`:''}</div>`).join('')||'<p class="small-note">No event suggestions yet.</p>'}</div><div class="footnote">This local admin screen is a prototype. A deployed service should add audit review, rate-limiting, and a formal moderation policy.</div>`;}
function renderAdminPerson(p){const score=p.overall_profile_score||{};return `<article class="candidate-card"><div class="candidate-heading"><div class="avatar">${esc(initials(p.name))}</div><div><h4>${esc(p.name)} ${p.is_demo?'<span class="tag orange">Demo</span>':''}</h4><p>${esc(p.email)} · ${esc(p.college||'College not listed')}</p></div></div><div class="score-pair"><span class="score-pill"><b>Profile ${Number(score.score||0)}/100</b></span>${p.discoverable?'<span class="tag green">Discoverable</span>':'<span class="tag">Hidden</span>'}</div><p class="small-note">${esc((p.skills||[]).join(' · ')||'No skills added yet')}<br>${esc(p.city||'Location not set')} · ${esc(p.course||'Course not set')}</p><p class="small-note">Evidence: ${esc(score.confidence_label||'Early profile')}</p><div class="footnote">This account can sign in using its own credentials and edit its own profile. Passwords are never shown here.</div></article>`;}
function renderAdminCase(c){return `<article class="admin-case"><div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div><h4>${esc(c.target_name)} · ${esc(c.event_name)}</h4><p>Team: ${esc(c.team_name)} · ${c.report_count}/${c.required_threshold} reports · Status <b>${esc(c.status)}</b></p></div><span class="tag ${c.status==='upheld'?'red':c.status==='dismissed'?'green':'orange'}">${esc(c.status)}</span></div>${c.response_text?`<div class="warning-panel"><strong>Reported person's response</strong>${esc(c.response_text)}</div>`:'<p>The reported person has not submitted a response.'}<p><b>Reports</b></p>${c.reports.map(r=>`<div class="request-row"><div class="request-row-main"><b>${esc(r.reporter_name)}</b><p>${esc(r.explanation)}</p></div><span class="tag">${dateFmt(r.created_at,{month:'short',day:'numeric'})}</span></div>`).join('')}<div class="field"><label>Moderator note</label><textarea id="admin-case-note-${c.id}" class="textarea" placeholder="Record the basis for your decision…">${esc(c.moderator_note||'')}</textarea></div><div class="heading-actions"><button class="btn btn-primary btn-sm" data-action="review-case" data-id="${c.id}" data-decision="uphold">Uphold after review</button><button class="btn btn-outline btn-sm" data-action="review-case" data-id="${c.id}" data-decision="dismiss">Dismiss / remove tag</button><button class="btn btn-ghost btn-sm" data-action="review-case" data-id="${c.id}" data-decision="review">Keep under review</button></div></article>`;}

function renderModal(){if(!state.modal)return '';const m=state.modal;if(m.type==='event'){const e=m.event;return `<div class="modal-backdrop" data-action="close-modal-bg"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="tag ${e.is_demo?'orange':'teal'}">${e.is_demo?'Sample event':'Event record'}</span><h3 style="margin-top:10px">${esc(e.name)}</h3><p>${esc(e.organizer)} · ${esc(e.location)} · ${esc(e.mode)}</p></div><button class="modal-close" data-action="close-modal">×</button></div><p style="font-size:12px;line-height:1.8;color:#647189">${esc(e.description)}</p><div class="grid grid-2" style="margin:16px 0"><div class="stat-card"><div class="stat-icon teal">◷</div><div><div class="stat-label">Event dates</div><div style="font-size:11px;font-weight:800;margin-top:5px">${dateFmt(e.event_start)} – ${dateFmt(e.event_end)}</div></div></div><div class="stat-card"><div class="stat-icon purple">♧</div><div><div class="stat-label">Team size</div><div style="font-size:11px;font-weight:800;margin-top:5px">${e.min_team_size}–${e.max_team_size} primary members</div></div></div></div><div class="card-head"><div><h3>Required or useful skills</h3></div></div><div class="skill-chips">${(e.required_skills||[]).map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')}</div><div class="data-notice">Deadline: ${dateFmt(e.registration_deadline)}. Source: ${esc(e.source_label)}. Confirm eligibility and any backup-member rules with the organiser before committing.</div><div class="heading-actions"><button class="btn ${e.interested?'btn-soft':'btn-outline'}" data-action="event-interest" data-id="${e.id}" data-interested="${e.interested?'false':'true'}">${e.interested?'✓ Interested':'＋ Mark interested'}</button><button class="btn btn-primary" data-action="find-for-event" data-id="${e.id}">Find / build a team →</button>${e.registration_url?`<a href="${esc(e.registration_url)}" class="btn btn-outline" target="_blank" rel="noopener">Official registration ↗</a>`:''}</div></section></div>`;}
if(m.type==='profile'){const p=m.profile;return `<div class="modal-backdrop" data-action="close-modal-bg"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="tag teal">Student profile</span><h3 style="margin-top:10px">${esc(p.name)}</h3><p>${esc(p.college||'College not listed')} · ${esc(p.city||'Location not listed')}</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="score-summary">${scoreRing(p.overall_profile_score.score)}<div><h3>Overall Profile Score</h3><p>${esc(p.overall_profile_score.confidence_label)} · ${p.overall_profile_score.confidence}% evidence confidence</p></div></div><div class="divider"></div><p style="font-size:11px;line-height:1.7;color:#68758b">${esc(p.bio||'No bio supplied.')} ${esc(p.profile_goal||'')}</p><div class="section-row"><div><h3>Skills</h3></div></div><div class="skill-chips">${(p.skills||[]).map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')||'No declared skills'}</div><div class="section-row"><div><h3>Evidence and profile links</h3></div></div>${(p.projects||[]).map(pr=>`<div class="request-row"><div class="request-row-main"><b>${esc(pr.name)}</b><p>${esc(pr.description||'No description')} · ${esc(pr.evidence_status||'self-reported')}${pr.url?`<br><a class="text-btn" href="${esc(pr.url)}" target="_blank" rel="noopener">Open evidence ↗</a>`:''}</p></div></div>`).join('')||'<p class="small-note">No project entries supplied.</p>'}${p.github_url?`<p class="small-note"><a class="text-btn" href="${esc(p.github_url)}" target="_blank" rel="noopener">GitHub profile ↗</a></p>`:''}${p.linkedin_url?`<p class="small-note"><a class="text-btn" href="${esc(p.linkedin_url)}" target="_blank" rel="noopener">LinkedIn profile ↗</a> · A link alone is not verified evidence.</p>`:''}${(p.deserter_tags||[]).map(tag=>`<div class="tag-card"><h4>⚑ ${esc(tag.label)}</h4><p>${esc(tag.event)} · ${esc(tag.explanation)} Status: ${esc(tag.status)}.</p></div>`).join('')}${p.id!==state.user.id?`<div class="divider"></div><button class="btn btn-danger btn-sm" data-action="block-user" data-id="${p.id}">Block this user</button>`:''}<div class="footnote">The Team Compatibility Score is intentionally not shown on this profile. It is computed only inside an authorised captain's team-matching workflow.</div></section></div>`;}
if(m.type==='report'){return `<div class="modal-backdrop" data-action="close-modal-bg"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="tag red">Trust report</span><h3 style="margin-top:10px">Report a possible no-show</h3><p>${esc(m.targetName)} · ${esc(m.eventName)}</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="warning-panel"><strong>Report the missed commitment, not poor performance.</strong> Use this only if the teammate accepted a primary role, failed to show up as agreed, and did not give prior notice or a reasonable explanation. The warning requires multiple distinct eligible reports and may be disputed.</div><form id="deserter-report-form" data-team="${m.teamId}" data-target="${m.targetId}"><div class="field"><label>What happened? (minimum 10 characters)</label><textarea class="textarea" name="explanation" minlength="10" required placeholder="Describe the event-day commitment and the missed attendance factually…"></textarea></div><button class="btn btn-danger" type="submit">Submit report for threshold review</button></form></section></div>`;}
if(m.type==='suggest-event'){return `<div class="modal-backdrop" data-action="close-modal-bg"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="tag blue">Event discovery</span><h3 style="margin-top:10px">Suggest an event</h3><p>Send a source link to the platform admin for review.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form id="suggest-event-form"><div class="field"><label>Event name</label><input class="input" name="name" required minlength="3"></div><div class="field"><label>Official event URL</label><input class="input" name="url" type="url" placeholder="https://…"></div><div class="field"><label>Why might this event be useful?</label><textarea class="textarea" name="reason" placeholder="Location, tracks, eligibility, or deadline details to verify…"></textarea></div><button class="btn btn-primary" type="submit">Send event suggestion →</button></form></section></div>`;}
return '';}

// ------------------------- delegated interactions -------------------------
document.addEventListener('click', async ev=>{
 const demo=ev.target.closest('[data-demo-email]');if(demo){$('#login-email').value=demo.dataset.demoEmail;$('#login-password').value='Campus123!';$('#auth-error').innerHTML='<div class="auth-notice">Demo credentials filled. Sign in to continue.</div>';return;}
 const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();navigate(nav.dataset.nav);return;}
 const actionEl=ev.target.closest('[data-action]');if(!actionEl)return;const a=actionEl.dataset.action;const id=Number(actionEl.dataset.id||0);const role=actionEl.dataset.role;
 try{
 switch(a){
  case'toggle-auth-mode':{const login=$('#login-form'),reg=$('#register-form');const showRegister=reg.classList.contains('hidden');login.classList.toggle('hidden',showRegister);reg.classList.toggle('hidden',!showRegister);$('#auth-title').textContent=showRegister?'Create your account':'Welcome back';$('#auth-sub').textContent=showRegister?'Set up your profile and start finding relevant opportunities.':'Sign in to continue discovering events and building your team.';$('#auth-toggle-copy').textContent=showRegister?'Already have an account?':'New to Campus Connect?';$('#auth-toggle-btn').textContent=showRegister?'Sign in':'Create an account';$('#auth-error').innerHTML='';return;}
  case'logout':await api('/api/auth/logout',{method:'POST'});state.user=null;state.dashboard=null;state.currentTeam=null;render();return;
  case'toggle-menu':$('#sidebar').classList.toggle('open');$('#mobile-overlay').classList.toggle('show');return;
  case'open-event':{const d=await api(`/api/events/${id}`);state.modal={type:'event',event:d.event};render();return;}
  case'close-modal':state.modal=null;render();return;
  case'close-modal-bg':if(ev.target===actionEl){state.modal=null;render();}return;
  case'event-interest':{const interested=actionEl.dataset.interested==='true';const d=await api(`/api/events/${id}/interest`,{method:'POST',body:{interested}});state.modal={type:'event',event:d.event};await loadEvents();if(state.dashboard)await refreshDashboard();render();toast(interested?'Event added to your interested list':'Event interest removed');return;}
  case'find-for-event':{const eid=id;state.modal=null;state.findEventId=String(eid);navigate('find-team',{eventId:eid});return;}
  case'filter-events':state.eventFilters.q=$('#event-search')?.value.trim()||'';state.eventFilters.location=$('#event-location')?.value.trim()||'';state.eventFilters.category=$('#event-category')?.value||'all';state.eventFilters.status=$('#event-status')?.value||'';await loadEvents();render();return;
  case'refresh-open-teams':await loadOpenTeams();render();toast('Open teams refreshed');return;
  case'filter-open-teams':state.findEventId=$('#open-team-event')?.value||'';await loadOpenTeams();const q=$('#open-team-search')?.value.trim().toLowerCase()||'';if(q)state.openTeams=state.openTeams.filter(t=>(t.name+' '+t.goal+' '+t.event_name).toLowerCase().includes(q));render();return;
  case'open-team':navigate('team-detail',{teamId:id});return;
  case'run-match':{state.matchRole=role||'primary';if(!state.currentTeam)return;const d=await api(`/api/teams/${state.currentTeam.team.id}/match`,{method:'POST',body:{target_role:state.matchRole,recovery:state.currentTeam.team.status==='recovery_needed'}});state.matchResult=d;render();toast(`Team Architect returned ${d.candidates.length} candidate(s)`,d.candidates.length?'success':'error',`Run #${d.run_id} · ${d.llm_configured?d.llm_provider:'deterministic'} workflow`);return;}
  case'invite-all-suggested':{if(!state.currentTeam||!state.matchResult)return;const teamId=state.currentTeam.team.id;const result=state.matchResult;const suggestedIds=(result.suggested_candidate_ids||[]).slice();if(!suggestedIds.length){toast('No suggested invitation slots remain. Run Team Architect again after resolving pending requests.','error');return;}actionEl.disabled=true;const d=await api(`/api/teams/${teamId}/requests/bulk`,{method:'POST',body:{candidate_ids:suggestedIds,run_id:Number(actionEl.dataset.run||result.run_id),role:role||result.target_role||state.matchRole}});state.matchResult={...result,suggested_candidate_ids:[],invite_limit:0,invited_candidate_ids:(d.invited||[]).map(x=>x.candidate_id)};await loadTeam(teamId);state.matchResult={...state.matchResult,suggested_candidate_ids:[],invite_limit:0,invited_candidate_ids:(d.invited||[]).map(x=>x.candidate_id)};await loadInbox();render();toast(`${d.invited_count} invitation(s) sent`,d.invited_count?'success':'error',d.skipped_count?`${d.skipped_count} candidate(s) skipped: ${(d.skipped||[]).map(x=>x.reason).join('; ')}`:'Each invitee must sign in and individually accept or decline.');return;}
  case'set-match-role':state.matchRole=role||'primary';render();return;
  case'invite-candidate':{const teamId=state.currentTeam.team.id;const chosenRole=role||state.matchRole;const d=await api(`/api/teams/${teamId}/requests`,{method:'POST',body:{candidate_id:id,role:chosenRole,role_label:chosenRole==='backup'?'Designated backup':'Primary member',message:`Campus Connect recommended this team based on event requirements and complementary skills. Please review the event and accept only if you can commit.`}});toast(d.message);await loadTeam(teamId);await loadInbox();render();return;}
  case'respond-request':{const requestId=id, choice=actionEl.dataset.choice;const d=await api(`/api/requests/${requestId}/respond`,{method:'POST',body:{action:choice}});toast(choice==='accept'?'Response accepted and team state updated':'Response declined; the captain will receive updated recovery suggestions','success',d.message);await loadInbox();await refreshDashboard();const teamId=Number(d.team_id||actionEl.closest('[data-team-id]')?.dataset.teamId||state.currentTeam?.team?.id||0);if(d.recovery_run_id&&teamId){navigate('team-detail',{teamId,runId:d.recovery_run_id});}else if(choice==='accept'&&teamId){navigate('team-detail',{teamId});}else if(state.route==='team-detail'&&state.currentTeam){await loadTeam(state.currentTeam.team.id);render();}else render();return;}
  case'promote-backup':{const d=await api(`/api/teams/${id}/promote-backup`,{method:'POST'});toast(d.message);await loadTeam(id);await loadInbox();render();return;}
  case'withdraw-team':if(!confirm('Withdraw from this team? The captain will be notified, and a primary-member withdrawal can trigger recovery.'))return;{const reason=prompt('Optional note to your captain (leave blank if you prefer):','')||'';const d=await api(`/api/teams/${id}/withdraw`,{method:'POST',body:{reason}});toast(d.message);await refreshDashboard();if(state.route==='team-detail')await loadTeam(id);render();return;}
  case'view-profile':{const d=await api(`/api/profile/${id}`);state.modal={type:'profile',profile:d.profile};render();return;}
  case'block-user':{if(!confirm('Block this student from future teammate recommendations and requests?'))return;const d=await api(`/api/users/${id}/block`,{method:'POST'});state.modal=null;render();toast(d.message);return;}
  case'toggle-candidate-detail':{const box=$(`#candidate-detail-${id}`);if(box)box.classList.toggle('open');return;}
  case'read-message':await api(`/api/inbox/${id}/read`,{method:'POST'});await loadInbox();if(state.dashboard)await refreshDashboard();render();return;
  case'read-all':await api('/api/inbox/read-all',{method:'POST'});await loadInbox();if(state.dashboard)await refreshDashboard();render();toast('Inbox marked as read');return;
  case'open-recovery':navigate('team-detail',{teamId:Number(actionEl.dataset.team),runId:Number(actionEl.dataset.run||0)});return;
  case'respond-case-view':state.modal=null;navigate('profile');return;
  case'report-deserter':{const d=await api(`/api/teams/${Number(actionEl.dataset.team)}/reviewables`);const m=(d.members||[]).find(x=>x.user_id===id);state.modal={type:'report',teamId:Number(actionEl.dataset.team),targetId:id,targetName:m?.name||'Teammate',eventName:d.event?.name||'Completed event'};render();return;}
  case'respond-case':{const response=$(`#case-response-${id}`)?.value.trim()||'';const d=await api(`/api/deserter-cases/${id}/respond`,{method:'POST',body:{response}});toast(d.message);await loadProfile();render();return;}
  case'suggest-event':state.modal={type:'suggest-event'};render();return;
  case'review-case':{const note=$(`#admin-case-note-${id}`)?.value||'';const decision=actionEl.dataset.decision;const d=await api(`/api/admin/deserter-cases/${id}/review`,{method:'POST',body:{decision,note}});toast(`Case updated: ${d.status}`);await loadAdmin();render();return;}
  case'accept-proposal':{await api(`/api/admin/event-proposals/${id}/accept`,{method:'POST'});await loadAdmin();render();toast('Event suggestion marked reviewed');return;}
  default:break;
 }
 }catch(err){toast(err.message,'error');}
});

document.addEventListener('submit', async ev=>{
 const form=ev.target;if(!(form instanceof HTMLFormElement))return;ev.preventDefault();
 try{
  if(form.id==='login-form'){
   $('#auth-error').innerHTML='';const fd=new FormData(form);const d=await api('/api/auth/login',{method:'POST',body:{email:fd.get('email'),password:fd.get('password')}});state.user=d.user;state.route='overview';await refreshDashboard();render();toast(`Welcome back, ${d.user.name.split(' ')[0]}`);return;
  }
  if(form.id==='register-form'){
   $('#auth-error').innerHTML='';const fd=new FormData(form);const d=await api('/api/auth/register',{method:'POST',body:{name:fd.get('name'),email:fd.get('email'),password:fd.get('password'),college:fd.get('college'),city:fd.get('city')}});state.user=d.user;state.route='profile';await refreshDashboard();render();toast('Account created. Complete your profile to improve matching.');return;
  }
  if(form.id==='create-team-form'){
   const fd=new FormData(form);const d=await api('/api/teams',{method:'POST',body:{event_id:Number(fd.get('event_id')),name:fd.get('name'),goal:fd.get('goal')}});await refreshDashboard();navigate('team-detail',{teamId:d.team.id});toast('Team created','success','The captain is the first confirmed primary member.');return;
  }
  if(form.id==='profile-form'){
   const fd=new FormData(form);const split=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean);const body={name:fd.get('name'),college:fd.get('college'),course:fd.get('course'),year:fd.get('year'),city:fd.get('city'),bio:fd.get('bio'),preferred_mode:fd.get('preferred_mode'),travel_radius:Number(fd.get('travel_radius')||0),availability:split(fd.get('availability')),skills:split(fd.get('skills')),interests:split(fd.get('interests')),roles:split(fd.get('roles')),work_preferences:split(fd.get('work_preferences')),profile_goal:fd.get('profile_goal'),github_username:fd.get('github_username')?.trim(),github_url:fd.get('github_url')?.trim(),linkedin_url:fd.get('linkedin_url')?.trim(),portfolio_url:fd.get('portfolio_url')?.trim(),projects:parseLines(fd.get('projects'),'project'),hackathons:parseLines(fd.get('hackathons'),'hackathon'),discoverable:fd.get('discoverable')==='on',notification_preference:fd.get('notification_preference')||'in_app'};const d=await api('/api/profile',{method:'PATCH',body});state.user=d.user;state.profileCache=d.user;await refreshDashboard();render();toast('Profile saved','success','Scores were recalculated from the latest available evidence.');return;
  }
  if(form.id==='github-search-form'){
   const q=$('#github-query').value.trim(), language=$('#github-language').value.trim();state.githubQuery=q;state.githubResults=null;render();const params=new URLSearchParams({q,language});const d=await api(`/api/github/search?${params.toString()}`);state.githubResults=d;render();toast(d.live?'Live GitHub results loaded':'Offline fallback loaded',d.live?'success':'error',d.notice);return;
  }
  if(form.id==='deserter-report-form'){
   const fd=new FormData(form);const d=await api(`/api/teams/${form.dataset.team}/deserter-reports`,{method:'POST',body:{target_id:Number(form.dataset.target),explanation:fd.get('explanation')}});state.modal=null;await loadTeam(Number(form.dataset.team));await loadProfile();render();toast(d.message,d.case.tag_active?'error':'success',d.case.tag_active?'The warning is event-specific and can be disputed.':`Current report count: ${d.case.report_count}/${d.case.required_threshold||'manual review'}`);return;
  }
  if(form.dataset.form==='review'){
   const fd=new FormData(form);const body={target_id:Number(form.dataset.target),contribution:Number(fd.get('contribution')),reliability:Number(fd.get('reliability')),teamwork:Number(fd.get('teamwork')),communication:Number(fd.get('communication')),role_fulfilment:Number(fd.get('role_fulfilment')),comment:fd.get('comment')||'',report_deserter:false,desertion_details:''};const d=await api(`/api/teams/${form.dataset.team}/reviews`,{method:'POST',body});await loadTeam(Number(form.dataset.team));render();toast('Teammate review saved');return;
  }
  if(form.id==='suggest-event-form'){
   const fd=new FormData(form);const d=await api('/api/event-proposals',{method:'POST',body:{name:fd.get('name'),url:fd.get('url'),reason:fd.get('reason')}});state.modal=null;render();toast(d.message);return;
  }
  if(form.id==='admin-person-form'){
   const fd=new FormData(form);const split=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean);const body={name:fd.get('name'),email:fd.get('email'),password:fd.get('password'),college:fd.get('college'),course:fd.get('course'),year:fd.get('year'),city:fd.get('city'),bio:fd.get('bio'),profile_goal:fd.get('profile_goal'),skills:split(fd.get('skills')),interests:split(fd.get('interests')),roles:split(fd.get('roles')),availability:split(fd.get('availability')),work_preferences:split(fd.get('work_preferences')),github_username:fd.get('github_username')?.trim(),github_url:fd.get('github_url')?.trim(),linkedin_url:fd.get('linkedin_url')?.trim(),portfolio_url:fd.get('portfolio_url')?.trim(),projects:parseLines(fd.get('projects'),'project'),hackathons:parseLines(fd.get('hackathons'),'hackathon'),discoverable:fd.get('discoverable')==='on'};const d=await api('/api/admin/people',{method:'POST',body});await loadAdmin();render();toast('Candidate account created','success','They can sign in with the credentials you created and accept/decline invitations from their own inbox.');return;
  }
  if(form.id==='admin-event-form'){
   const fd=new FormData(form);const split=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean);const body={name:fd.get('name'),organizer:fd.get('organizer'),category:fd.get('category'),mode:fd.get('mode'),location:fd.get('location'),required_skills:split(fd.get('required_skills')),event_start:fd.get('event_start'),event_end:fd.get('event_end'),registration_deadline:fd.get('registration_deadline'),min_team_size:Number(fd.get('min_team_size')),max_team_size:Number(fd.get('max_team_size')),source_url:fd.get('source_url'),registration_url:fd.get('registration_url'),description:fd.get('description'),eligibility:fd.get('eligibility'),source_label:'Admin supplied · verify official details',status:'upcoming'};await api('/api/admin/events',{method:'POST',body});await loadAdmin();await loadEvents();render();toast('Event record added','success','Verify the date, eligibility and source with the organiser.');return;
  }
 }catch(err){if(form.id==='login-form'||form.id==='register-form')$('#auth-error').innerHTML=`<div class="auth-error">${esc(err.message)}</div>`;else toast(err.message,'error');}
});

// Inputs, search and keyboard shortcuts.
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.modal){state.modal=null;render();}if(ev.key==='Enter'&&ev.target.id==='global-search'){ev.preventDefault();state.eventFilters.q=ev.target.value.trim();navigate('discover');}});
$('#app').addEventListener('input', ev=>{if(ev.target.id==='global-search'&&state.route==='discover'){state.eventFilters.q=ev.target.value;}});

async function start(){
 try{const demo=await api('/api/demo-accounts');state.demoEnabled=Boolean(demo.enabled);}catch(_){state.demoEnabled=false;}
 try{const d=await api('/api/me');state.user=d.user;await refreshDashboard();state.route='overview';render();}
 catch(_){state.user=null;render();}
}
start();
